-- Items table for PostgreSQL. Run once on an EXISTING database
-- (with CreateIfMissing=true the API creates a brand-new database by itself).
-- EF Core/Npgsql uses quoted PascalCase identifiers.
CREATE TABLE IF NOT EXISTS "Items" (
    "Id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name"        varchar(120)  NOT NULL,
    "Type"        varchar(20)   NOT NULL,  -- Feature | Service | Tool
    "Status"      varchar(20)   NOT NULL,  -- Active | InDevelopment | Deprecated
    "Description" varchar(1000) NOT NULL,
    "OwnerTeam"   varchar(120)  NOT NULL,
    "Contact"     varchar(120)  NOT NULL,
    "RepoUrl"     varchar(500)  NULL,
    "DocsUrl"     varchar(500)  NULL,
    "Tags"        text[]        NOT NULL DEFAULT '{}',
    "CreatedAt"   timestamp with time zone NOT NULL,
    "UpdatedAt"   timestamp with time zone NOT NULL
);
CREATE INDEX IF NOT EXISTS "IX_Items_Name" ON "Items" ("Name");
CREATE INDEX IF NOT EXISTS "IX_Items_OwnerTeam" ON "Items" ("OwnerTeam");

